import {icon} from './icons.js';
// Form atoms shared by the application and component reference.
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

export function createFormComponents(getData,getErrors){
const errorFor=id=>getErrors()[id]?`<p class="error field-error" id="${id}-error">${icon('info',14)}<span>${esc(getErrors()[id])}</span></p>`:'';
const attrs=id=>`${getErrors()[id]?'aria-invalid="true" ':''}aria-describedby="${id}-hint${getErrors()[id]?` ${id}-error`:''}"`;
function field(id,label,{type='text',placeholder='',full=false,optional=false,hint='',readonly=false,disabled=false,autocomplete=''}={}){const data=getData(),errors=getErrors();return `<div class="field ${full?'full':''} ${errors[id]?'has-error':''}"><label for="${id}">${label}${optional?'<span class="optional">Optional</span>':''}</label>${type==='date'?'<div class="date-control">':''}<input id="${id}" name="${id}" type="${type}" value="${esc(data[id])}" placeholder="${esc(placeholder)}" ${readonly?'readonly':''} ${disabled?'disabled':''} ${attrs(id)} ${autocomplete?'autocomplete="'+esc(autocomplete)+'"':id==='dob'?'autocomplete="bday"':type==='email'?'autocomplete="email" autocapitalize="none" spellcheck="false"':id==='fullName'?'autocomplete="name"':type==='tel'?'autocomplete="tel-national" inputmode="tel"':id==='otp'?'autocomplete="one-time-code" inputmode="numeric"':''}>${type==='date'?icon('calendar',18)+'</div>':''}<p id="${id}-hint" class="hint">${hint}</p>${errorFor(id)}</div>`;}
function select(id,label,options,{full=false,hint=''}={}){const data=getData(),errors=getErrors();return `<div class="field ${full?'full':''} ${errors[id]?'has-error':''}"><label for="${id}">${label}</label><div class="select-control"><select id="${id}" name="${id}" ${(id==='nationality'&&/^\d{12}$/.test(data.nric))||(id==='liability'&&!options.length)?'disabled':''} ${attrs(id)}><option value="">Select ${label.toLowerCase()}</option>${options.map(o=>`<option value="${esc(o)}" ${data[id]===o?'selected':''}>${esc(o)}</option>`).join('')}</select>${icon('chevron',18)}</div><p class="hint" id="${id}-hint">${hint}</p>${errorFor(id)}</div>`;}
function question(id,text,options=['Yes','No']){const data=getData(),errors=getErrors();let v=id.startsWith('q')?data.answers?.[id]:data[id];return `<div class="question ${errors[id]?'has-error':''}"><fieldset ${errors[id]?`aria-invalid="true" aria-describedby="${id}-error"`:''}><legend>${text}</legend><div class="choices ${options.length===2&&options.every(o=>['Yes','No','Agree','Disagree','Male','Female'].includes(o))?'binary':''}">${options.map(o=>`<label class="choice"><input type="radio" name="${id}" value="${esc(o)}" ${v===o?'checked':''}>${esc(o)}</label>`).join('')}</div>${errorFor(id)}</fieldset></div>`;}
function textarea(id,label,{full=true,hint='',rows=4,readonly=false}={}){return `<div class="field ${full?'full':''} ${getErrors()[id]?'has-error':''}"><label for="${id}">${label}</label><textarea id="${id}" name="${id}" rows="${rows}" ${readonly?'readonly':''} ${attrs(id)}>${esc(getData()[id])}</textarea><p id="${id}-hint" class="hint">${hint}</p>${errorFor(id)}</div>`;}
function check(id,html){const data=getData(),errors=getErrors();return `<div class="check-row"><input type="checkbox" name="${id}" id="${id}" aria-labelledby="${id}-label" ${data[id]?'checked':''} ${errors[id]?`aria-invalid="true" aria-describedby="${id}-error"`:''}><div id="${id}-label">${html.includes('<')?`<span>${html}</span>`:`<label for="${id}" class="check-label">${html}</label>`}</div></div>${errorFor(id)}`;}

return {field,textarea,select,question,check,errorFor,attrs};
}
